45	/** Thrown when a compare-and-swap shows someone else already advanced the period. */
46	class AlreadyRenewedError extends Error {}
47	
48	const DOMAIN_RENEW_WINDOW_DAYS = 7;
49	const DAY = 86400_000;
50	
51	/* ------------------------------------------------------------------ *
52	 * CARD AUTO-CHARGE + DUNNING
53	 *
54	 * A renewal applies wallet credit FIRST and auto-charges the saved card for the
55	 * remainder — the same split `lib/wallet-split.ts` gives checkout, so a renewal
56	 * behaves exactly like a purchase and prepaid/referral/refund credit gets drained
57	 * instead of accumulating as a liability.
58	 *
59	 * When the card fails the customer is NOT suspended. The card is retried on days
60	 * 1, 3 and 5 past expiry, each with its own email, and only once every attempt is
61	 * spent — plus one clear day after the final notice — does the server pause. The
62	 * old behaviour sent a customer with a perfectly good card straight to SUSPENDED
63	 * the moment their wallet emptied, and told them about it with nothing but a bell
64	 * icon in a portal they had stopped visiting.
65	 * ------------------------------------------------------------------ */
66	
67	/**
68	 * Days past expiry for retry N (1-based): 1, 3, 5 …
69	 *
70	 * Derived from DUNNING_RETRY_ATTEMPTS — the same constant `emails.paymentRetryFailed`
71	 * uses to tell the customer how many attempts remain — so the schedule the worker
72	 * runs and the number in the email can never drift apart.
73	 */
74	const retryDayFor = (retry: number) => 2 * retry - 1;
75	/** Days past expiry of the LAST automatic retry. */
76	const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
77	/** One clear day between the final-notice email and the suspension it warns about. */
78	const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;
79	/** `Server.dunningStage` once the attempt on expiry day AND every retry have failed. */
80	const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
81	/**
82	 * Never schedule a retry sooner than this. The sweep runs every 10 minutes, so a
83	 * worker that was down for a week would otherwise burn every retry — and every
84	 * email — in the space of one afternoon.
85	 */
86	const MIN_RETRY_GAP_MS = 20 * 3600_000;
87	/** How soon to re-try after an error that was OUR side, not the customer's. */
88	const TRANSIENT_RETRY_MS = 60 * 60_000;
89	/**
90	 * Hard cap on how far a late-starting or error-delayed sequence may push a
91	 * suspension past its calendar date. `suspendDueAt` waits for a retry we have
92	 * PROMISED the customer, and a Stripe outage reschedules that promise hourly
93	 * forever — without this cap "never suspend mid-sequence" would quietly become
94	 * "never suspend at all".
95	 */
96	const SUSPEND_SLIP_CAP_DAYS = 4;
97	/** Warn about a saved card this many days before it expires. */
98	const CARD_EXPIRY_WARN_DAYS = 30;
99	/** Re-nudge about a still-unreplaced expiring/expired card at most this often. */
100	const CARD_EXPIRY_RENUDGE_DAYS = 60;
101	/** Ledger description prefix that identifies an automatic wallet top-up. */
102	const AUTO_RECHARGE_DESC = "Automatic wallet top-up";
103	/** Mirrors the floor `saveAutoRecharge` enforces on the customer's own input. */
104	const AUTO_RECHARGE_MIN_CENTS = 500;
105	
106	/**
107	 * Dunning windows, all measured in DAYS PAST EXPIRY.
108	 *
109	 * Settings → Billing is the source of truth. Those three fields and the
110	 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
111	 * read by NOTHING: the worker used env vars that were never set, so an operator who
112	 * turned suspensions off during an incident saw "Saved." and then watched the sweep
113	 * knock customer VMs offline ten minutes later.
114	 *
115	 * The legacy env vars remain as fallbacks, converted onto the days-past-expiry clock
116	 * so an operator who had set them keeps the behaviour they configured
117	 * (NXEON_TERMINATE_DAYS counted forward from the END of grace, and
118	 * NXEON_WARN_BEFORE_TERMINATE_DAYS counted backwards from termination).
119	 */
120	type DunningConfig = {
121	  /** Days past expiry before an account with no card in play is suspended. */
122	  graceDays: number;
123	  /** Days past expiry when the "will be deleted" warning goes out. */
124	  warnDays: number;
125	  /** Days past expiry when an unpaid SUSPENDED server is destroyed. */
126	  terminateDays: number;
127	  /** Admin kill switch: when false the sweep suspends and terminates nothing. */
128	  autoSuspend: boolean;
129	};
130	
131	const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
132	const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
133	  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
134	  : 14;
135	const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
136	  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
137	  : 7;
138	
139	async function dunningConfig(): Promise<DunningConfig> {
140	  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
141	  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
142	  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
143	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
144	
145	  // Clamp. These are free-text number fields in an admin panel and the action they
146	  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
147	  // same day it is suspended, or before the dunning sequence has even finished. The
148	  // floor includes the slip cap because a card sequence that started late can push
149	  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
150	  // termination must always land AFTER the suspension it follows.
151	  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
152	  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
153	  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
154	  return { graceDays, warnDays, terminateDays, autoSuspend };
155	}
