197	/** The renewal queue, and the row shape every card/dunning helper below works on. */
198	async function dueServers(now: Date) {
199	  return db.server.findMany({
200	    where: {
201	      isFree: false,
202	      expiresAt: { lt: now },
203	      status: { in: ["RUNNING", "STOPPED"] },
204	    },
205	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
206	  });
207	}
208	type DueServer = Awaited<ReturnType<typeof dueServers>>[number];
209	
210	/**
211	 * Subscription sweep, run periodically by the worker:
212	 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
213	 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
214	 *                                                 saved card for the remainder
215	 *  - card declined                             -> dunning (retry days 1/3/5 + email)
216	 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
217	 * Free servers (isFree) are never touched.
218	 */
219	export async function billingSweep() {
220	  const now = new Date();
221	  const cfg = await dunningConfig();
222	  const prices = {
223	    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
224	    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
225	    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
226	    // upsell keeps billing every cycle rather than being a one-off charge.
227	    extraDiskPerGbCents: await extraDiskPerGbCents(),
228	  };
229	
230	  // Claim any card that was saved at Stripe but never confirmed in the browser,
231	  // BEFORE the renewal queries read card state — otherwise a customer who closed
232	  // the tab on Stripe's page gets dunned for a card we simply failed to record.
233	  try {
234	    const adopted = await adoptUnclaimedCards(now);
235	    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
236	  } catch (e) {
237	    console.error("[billing] card adoption error", e);
238	  }
239	
240	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
241	  const soon = new Date(now.getTime() + 3 * 86400_000);
242	  const upcoming = await db.server.findMany({
243	    where: {
244	      isFree: false,
245	      expiresAt: { gt: now, lt: soon },
246	      status: { in: ["RUNNING", "STOPPED"] },
247	    },
248	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
249	  });
250	  for (const server of upcoming) {
251	    const warnCents = renewalCharge(server, prices).totalCents;
252	    // A customer with a card on file needs no warning and no top-up: the renewal
253	    // applies their wallet credit and auto-charges the card for the remainder.
254	    // Telling them to "top up to avoid suspension" would raise an alarm about a
255	    // suspension that is not going to happen.
256	    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableCard(server.user))) {
257	      continue;
258	    }
259	    const already = await db.notification.findFirst({
260	      where: {
261	        userId: server.userId,
262	        title: { contains: server.hostname },
263	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
264	        AND: { title: { contains: "renews soon" } },
265	      },
266	    });
267	    if (!already) {
268	      await db.notification.create({
269	        data: {
270	          userId: server.userId,
271	          title: `${server.hostname} renews soon — action needed`,
272	          body: server.autoRenew
273	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
274	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
275	          href: `/dashboard/servers/${server.id}`,
276	        },
277	      });
278	    }
279	  }
280	  const due = await dueServers(now);
281	
282	  for (const server of due) {
283	    // One unhappy server must never abort the queue behind it. Every money write
284	    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
285	    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
286	    // delayed renewal — never a duplicate charge. Without this, a single row with a
287	    // wedged Stripe customer would leave every later customer unrenewed AND
288	    // eventually suspended, for a fault that was entirely ours.
289	    try {
290	      await renewDueServer(server, { now, cfg, prices });
291	    } catch (e) {
292	      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
293	    }
294	  }
295	
296	  await terminateOverdue(now, cfg);
297	
298	  // Card housekeeping: nudge before a saved card expires, and honour the customer's
299	  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
300	  // can never take the renewal sweep down with it.
301	  try {
302	    await cardExpirySweep(now);
303	  } catch (e) {
304	    console.error("[billing] card-expiry sweep error", e);
305	  }
306	  try {
307	    await autoRechargeSweep(now);
308	  } catch (e) {
309	    console.error("[billing] auto-recharge sweep error", e);
310	  }
311	
312	  await domainAutoRenewSweep(now);
313	
314	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
315	  // domain upkeep all lives on one timer.
316	  try {
317	    await domainTransferInSweep(now);
318	  } catch (e) {
319	    console.error("[billing] domain transfer-in sweep error", e);
320	  }
321	}
