323	/**
324	 * One expired server: renew it from wallet + card, or move it along the dunning
325	 * sequence, or suspend it once every promised attempt is spent.
326	 */
327	async function renewDueServer(
328	  server: DueServer,
329	  ctx: { now: Date; cfg: DunningConfig; prices: { ipMonthlyCents: number; extraDiskPerGbCents: number } },
330	) {
331	  const { now, cfg, prices } = ctx;
332	  const charge = renewalCharge(server, prices);
333	  const renewCents = charge.totalCents;
334	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
335	  const newExpiry = addMonths(base, charge.months);
336	
337	  await clearStaleDunning(server);
338	
339	  let renewed = false;
340	  if (server.autoRenew) {
341	    // `server.user.balanceCents` came from a snapshot taken before this loop and
342	    // is stale as soon as the first renewal in this pass debits a wallet, so the
343	    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
344	    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
345	    // concurrent renewNow()/second pass charging the same period twice.
346	    const fresh = await db.user.findUnique({
347	      where: { id: server.userId },
348	      select: { balanceCents: true },
349	    });
350	    const split = walletSplit({
351	      dueCents: renewCents,
352	      balanceCents: fresh?.balanceCents ?? 0,
353	      useWallet: true,
354	    });
355	    const cardInPlay = hasChargeableCard(server.user);
356	
357	    if (split.cardCents === 0) {
358	      // Wallet covers the whole renewal — no card involved, no Stripe call.
359	      const outcome = await commitRenewal({ server, charge, newExpiry });
360	      renewed = outcome !== "insufficient";
361	      if (outcome === "renewed") {
362	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
363	      }
364	    } else if (cardInPlay) {
365	      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
366	      // would burn all three retries — and send all three emails — within half an
367	      // hour of the first decline.
368	      //
369	      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
370	      // two things. `retryDunningNow` (fired when a customer saves a new card
371	      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
372	      // would suspend a customer whose brand-new card we never once tried. And the
373	      // exhausted stage's schedule points at the suspension day itself, so every
374	      // server gets one final, silent try at the card in the same pass that pauses it.
375	      const dueForRetry = server.dunningNextAt
376	        ? now >= server.dunningNextAt
377	        : server.dunningStage < DUNNING_EXHAUSTED;
378	      if (dueForRetry) {
379	        renewed = await attemptCardRenewal({
380	          server,
381	          charge,
382	          cardCents: split.cardCents,
383	          newExpiry,
384	          now,
385	          cfg,
386	        });
387	      }
388	    } else {
389	      console.log(
390	        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
391	      );
392	    }
393	  }
394	
395	  if (renewed) {
396	    // nothing further this pass
397	  } else {
398	    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
399	    if (suspendAt && now >= suspendAt) {
400	      await suspendUnpaid(server, cfg);
401	    }
402	  }
403	}
404	
405	/**
406	 * Drop dunning state that belongs to a period we are no longer collecting for.
407	 *
408	 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
409	 * columns, so a customer who paid by hand halfway through a sequence carries a
410	 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
411	 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
412	 * compressed schedule, for a period they had never failed once.
413	 *
414	 * Every schedule this file writes lands at or after the expiry it was computed
415	 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
416	 * been written for an older, already-settled period.
417	 */
418	async function clearStaleDunning(server: DueServer): Promise<void> {
419	  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
420	  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
421	  if (belongsToThisPeriod) return;
422	
423	  await db.server.update({
424	    where: { id: server.id },
425	    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
426	  });
427	  // Keep the in-memory row honest: the rest of this pass reads these fields to
428	  // decide whether to charge, which email to send and when to suspend.
429	  server.dunningStage = 0;
430	  server.dunningNextAt = null;
431	  server.dunningPayUrl = null;
432	}
433	
434	/* ------------------------------------------------------------------ *
435	 * Renewal commit (wallet) + card auto-charge
436	 * ------------------------------------------------------------------ */
437	
438	/**
439	 * Advance the term and take the money from the wallet, atomically.
440	 *
441	 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
442	 * by a top-up, a referral credit or the saved card moments ago. One money path
443	 * means a partial failure can never half-apply a renewal: either the period
444	 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
445	 *
446	 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
447	 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
448	 * the first `updateMany` to match it writes, and every loser rolls back its debit
449	 * and its invoice with the transaction. Zero rows matched = someone else already
450	 * renewed this period, which is a success for us, not an error.
451	 */
452	async function commitRenewal(opts: {
453	  server: DueServer;
454	  charge: RenewalCharge;
455	  newExpiry: Date;
456	}): Promise<"renewed" | "insufficient" | "already"> {
457	  const { server, charge, newExpiry } = opts;
458	  const renewCents = charge.totalCents;
459	  const { extraDiskCents, extraDiskMonthlyCents } = charge;
460	  const periodStart = server.expiresAt!;
461	
462	  try {
463	    await db.$transaction(async (tx) => {
464	      const advanced = await tx.server.updateMany({
465	        where: { id: server.id, expiresAt: server.expiresAt },
466	        data: {
467	          expiresAt: newExpiry,
468	          // The period is paid, so the collection state that belonged to it dies
469	          // with it. Leaving a stage behind would hand the NEXT period a
470	          // half-spent retry budget and the wrong dunning email.

470	          // half-spent retry budget and the wrong dunning email.
471	          dunningStage: 0,
472	          dunningNextAt: null,
473	          dunningPayUrl: null,
474	        },
475	      });
476	      if (advanced.count === 0) throw new AlreadyRenewedError();
477	      await debitWallet(tx, server.userId, renewCents);
478	      await tx.walletTransaction.create({
479	        data: {
480	          userId: server.userId,
481	          amountCents: -renewCents,
482	          description: `Renewal: ${charge.label} (${server.hostname})`,
483	        },
484	      });
485	      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
486	      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
487	      // never producing a second invoice for the same period.
488	      await tx.invoice.create({
489	        data: invoiceCreateData({
490	          userId: server.userId,
491	          description: `Renewal: ${charge.label} (${server.hostname})`,
