614	        user.email,
615	        user.id,
616	        emails.paymentReceipt(
617	          fmtUsd(result.amountCents),
618	          `${charge.label} — ${server.hostname}`,
619	          user.cardLast4 ?? "",
620	        ),
621	      );
622	    }
623	
