733	async function recordDeclinedAttempt(opts: {
734	  server: DueServer;
735	  cardCents: number;
736	  now: Date;
737	  cfg: DunningConfig;
738	  reason: string;
739	}): Promise<void> {
740	  const { server, cardCents, now, cfg, reason } = opts;
741	  const prevStage = server.dunningStage;
742	  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
743	  const amount = fmtUsd(cardCents);
744	  const last4 = server.user.cardLast4 ?? "";
745	
746	  console.warn(`[billing] card declined for ${server.hostname} (attempt ${newStage}): ${reason}`);
