875	/**
876	 * When this overdue server may be paused — null means never (auto-suspend is off).
877	 *
878	 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
879	 * after the final-notice email, so the customer always gets a full day with the
880	 * warning in hand before anything stops. Without a card there is nothing to wait
881	 * for beyond the configured grace period.
882	 *
883	 * The deadline also never lands BEFORE a date we have promised the customer. A
884	 * worker that was down for the first five days starts the sequence late, and
885	 * suspending on the calendar alone would then pause a server minutes after emailing
886	 * "we'll try your card again on <date>" or "this is your final notice" — the exact
887	 * broken promise this whole feature exists to stop. `dunningNextAt` carries that
888	 * promise (the next attempt while any remain, the clear day once they are spent),
889	 * and the slip it can buy is capped by SUSPEND_SLIP_CAP_DAYS so a permanently
890	 * failing Stripe cannot defer suspension forever.
891	 */
892	function suspendDueAt(
893	  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
894	  hasCard: boolean,
895	  cfg: DunningConfig,
896	): Date | null {
897	  if (!cfg.autoSuspend || !server.expiresAt) return null;
898	  const days = calendarSuspendDay(cfg, hasCard);
899	  const at = new Date(server.expiresAt.getTime() + days * DAY);
900	  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
901	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
902	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
