1023	/**
1024	 * Honour the customer's own "keep my wallet topped up" preference.
1025	 *
1026	 * This is opt-in and customer-configured (`autoRechargeEnabled` /
1027	 * `autoRechargeThresholdCents` / `autoRechargeAmountCents`), and it is the only
1028	 * charge in this file that is NOT tied to a renewal — so unlike the renewal leg it
1029	 * DOES get its own invoice, because it is the whole payment rather than one part
1030	 * of a larger one.
1031	 *
1032	 * `autoRechargeMarker` is scoped to the account and the CALENDAR DAY, which caps
1033	 * this at one top-up per account per day no matter how many times the sweep runs
1034	 * or how fast the customer spends. Combined with the UNIQUE index on
1035	 * `WalletTransaction.stripePaymentIntentId`, a replayed capture credits once and
1036	 * emails once.
1037	 */
1038	async function autoRechargeSweep(now: Date): Promise<void> {
1039	  if (!stripeConfigured()) return;
1040	  const users = await db.user.findMany({
1041	    where: {
1042	      autoRechargeEnabled: true,
1043	      suspended: false,
1044	      stripeCustomerId: { not: null },
1045	      stripePaymentMethodId: { not: null },
1046	    },
1047	  });
1048	
1049	  for (const user of users) {
1050	    const threshold = user.autoRechargeThresholdCents ?? 0;
1051	    const amount = user.autoRechargeAmountCents ?? 0;
1052	    // A threshold of 0 means "never", and an amount below the floor the customer's
1053	    // own settings form enforces is a stale/hand-edited row — charging on either
1054	    // would be taking money the customer did not ask for.
1055	    if (threshold <= 0 || amount < AUTO_RECHARGE_MIN_CENTS) continue;
1056	    if (user.balanceCents >= threshold) continue;
1057	
1058	    const day = now.toISOString().slice(0, 10);
1059	    const marker = autoRechargeMarker(user.id, now);
1060	    let result: OffSessionResult;
1061	    try {
1062	      result = await chargeSavedCardOffSession({
1063	        user,
1064	        amountCents: amount,
1065	        description: `${AUTO_RECHARGE_DESC} — Nxeon wallet`,
1066	        marker,
1067	        idempotencyKey: `nxeon_autorecharge_${user.id}_${day}_${amount}`,
1068	        metadata: { nxeonKind: "auto_recharge" },
1069	      });
1070	    } catch (e) {
1071	      // One wedged account must not stop the others from topping up.
1072	      console.error(`[billing] auto-recharge error for ${user.email}`, e);
1073	      continue;
1074	    }
1075	
1076	    if (result.ok) {
1077	      const credited = await creditOffSessionCharge({
1078	        userId: user.id,
1079	        amountCents: result.amountCents,
1080	        description: `${AUTO_RECHARGE_DESC} (${savedCardLabel(user) ?? "saved card"})`,
1081	        paymentIntentId: result.paymentIntentId,
1082	        // This charge IS the whole payment, so it gets its own PAID invoice — in
1083	        // the same guarded write, so the invoice cannot outlive a rolled-back credit.
1084	        invoiceDescription: AUTO_RECHARGE_DESC,
1085	      });
1086	      if (!credited) continue; // already credited today — nothing new to announce
1087	      await mail(
1088	        user.email,
1089	        user.id,
1090	        emails.paymentReceipt(fmtUsd(result.amountCents), AUTO_RECHARGE_DESC, user.cardLast4 ?? ""),
1091	      );
1092	      await notify(
1093	        user.id,
1094	        `Wallet topped up ${fmtUsd(result.amountCents)}`,
1095	        `Your balance had dropped below ${fmtUsd(threshold)}, so we topped it up automatically using your saved card.`,
1096	        "/dashboard/billing",
1097	      );
1098	      console.log(`[billing] auto-recharged ${user.email} by ${fmtUsd(result.amountCents)}`);
1099	      continue;
1100	    }
1101	
1102	    if (result.kind === "unavailable") {
1103	      // The method is gone at Stripe. Clear it so the portal stops offering a card
1104	      // that cannot be charged (see the same branch in attemptCardRenewal).
1105	      await forgetMissingPaymentMethod(user.id).catch(() => {
1106	        /* best-effort */
1107	      });
1108	      continue;
1109	    }
1110	    if (result.kind !== "declined") continue; // transient / 3-D Secure: try again later, silently
1111	
1112	    // A declined top-up must NOT touch any server's dunning state — nothing is
1113	    // overdue, the customer simply asked us to keep a float. Tell them once a day
1114	    // and leave it there.
1115	    const already = await db.notification.findFirst({
1116	      where: {
1117	        userId: user.id,
1118	        title: { contains: "Automatic top-up" },
1119	        createdAt: { gt: new Date(now.getTime() - DAY) },
1120	      },
1121	    });
1122	    if (!already) {
1123	      await notify(
1124	        user.id,
1125	        "Automatic top-up declined",
1126	        `We couldn't charge ${fmtUsd(amount)} to your saved card for an automatic wallet top-up. Your services are unaffected — update your card when you get a moment.`,
1127	        "/dashboard/billing",
1128	      );
1129	    }
1130	  }
1131	}
