1140	/**
1141	 * Poll every TRANSFER_PENDING domain and move it to its real state.
1142	 *
1143	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
1144	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
1145	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
1146	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
1147	 *   pending   -> raw registrar status refreshed for display, gentle nudge
1148	 *
1149	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
1150	 * re-run, two workers racing, or a customer cancelling at the same moment can
1151	 * never credit the same transfer twice.
1152	 */
1153	async function domainTransferInSweep(now: Date) {
1154	  if (!transfersAvailable()) return; // registrar not configured — skip silently
1155	
1156	  const pending = await db.domain.findMany({
1157	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
1158	  });
1159	
1160	  for (const domain of pending) {
1161	    try {
1162	      const info = await getTransfer(domain.name, domain.transferStartedAt);
1163	
1164	      // No transfer on record. Normal once a transfer settles and drops off the
1165	      // registrar's list — resolve it against the account rather than guessing.
1166	      if (!info) {
1167	        const owned = await domainInfo(domain.name).catch(() => null);
1168	        if (owned?.expires) {
1169	          await completeTransferIn(domain, "completed", owned);
1170	          continue;
1171	        }
1172	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
1173	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
1174	        if (ageDays > TRANSFER_STALE_DAYS) {
1175	          await failTransferIn(
1176	            domain,
1177	            null,
1178	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
1179	          );
1180	        }
1181	        continue;
1182	      }
1183	
1184	      const outcome = transferOutcome(info.status);
1185	
1186	      if (outcome === "completed") {
1187	        const owned = await domainInfo(domain.name).catch(() => null);
1188	        await completeTransferIn(domain, info.status, owned);
1189	        continue;
1190	      }
1191	
1192	      if (outcome === "failed") {
1193	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
1194	        continue;
1195	      }
1196	
1197	      // Still in flight — keep the displayed registrar status fresh.
1198	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
1199	        await db.domain.update({
1200	          where: { id: domain.id },
1201	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
1202	        });
1203	      }
1204	      await nudgeTransferApproval(domain, info.status, info.email, now);
1205	    } catch (e) {
1206	      // One unhappy domain must never abort the sweep. Nothing is settled and
1207	      // no money moves on an unknown state — we simply try again next pass.
1208	      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
1209	    }
1210	  }
1211	}
