1301	/**
1302	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
1303	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
1304	 * A payment before this point unsuspends the server, so this only ever hits
1305	 * genuinely abandoned accounts. Free servers are never terminated.
1306	 *
1307	 * Both windows are measured in DAYS PAST EXPIRY and come from Settings → Billing
1308	 * (`dunningConfig`), clamped so termination can never land on or before the day the
1309	 * server was suspended — including the extra days a late-starting card dunning
1310	 * sequence is allowed to slip.
1311	 */
1312	async function terminateOverdue(now: Date, cfg: DunningConfig) {
1313	  // The admin kill switch covers deletion too. An operator who turns auto-suspend
1314	  // off during an incident means "stop taking servers away from customers", and
1315	  // the irreversible half of that is the half that must obey first.
1316	  if (!cfg.autoSuspend) return;
1317	
1318	  // ONLY unpaid suspensions. This used to select on `status: "SUSPENDED"` alone,
1319	  // while the renewal sweep EXCLUDES suspended servers — so an admin suspending a
1320	  // paid-up customer pending an abuse investigation meant that customer was never
1321	  // charged and never warned, their term quietly lapsed, and 13 days later this
1322	  // function destroyed their VM and all its data with a "prolonged non-payment"
1323	  // notice they had never been given the chance to act on. They had auto-renew on
1324	  // and money in their wallet the entire time.
1325	  //
1326	  // Legacy rows suspended before `suspendReason` existed have it null; those are
1327	  // deliberately excluded too. Failing to delete is always the safer error here —
1328	  // an un-terminated server costs disk, a wrongly-terminated one is unrecoverable.
1329	  const suspended = await db.server.findMany({
1330	    where: {
1331	      isFree: false,
1332	      status: "SUSPENDED",
1333	      suspendReason: "UNPAID",
1334	      expiresAt: { not: null },
1335	    },
1336	  });
1337	  for (const server of suspended) {
1338	    const terminateAt = server.expiresAt!.getTime() + cfg.terminateDays * DAY;
1339	    const warnAt = server.expiresAt!.getTime() + cfg.warnDays * DAY;
1340	
1341	    if (now.getTime() >= terminateAt) {
1342	      const pending = await db.job.count({
1343	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
1344	      });
1345	      if (pending > 0) continue;
1346	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
1347	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
1348	      await db.auditLog.create({
1349	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
1350	      });
1351	      await db.notification.create({
1352	        data: {
1353	          userId: server.userId,
1354	          title: `${server.hostname} was permanently deleted`,
1355	          body: "Your server and its data were removed after prolonged non-payment.",
1356	        },
1357	      });
1358	      console.log(`[billing] terminating abandoned ${server.hostname}`);
1359	    } else if (now.getTime() >= warnAt) {
1360	      const already = await db.notification.findFirst({
1361	        where: {
1362	          userId: server.userId,
1363	          title: { contains: server.hostname },
1364	          AND: { title: { contains: "will be deleted" } },
1365	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
1366	        },
1367	      });
1368	      if (!already) {
1369	        await db.notification.create({
1370	          data: {
1371	            userId: server.userId,
1372	            title: `${server.hostname} will be deleted soon`,
1373	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
1374	            href: `/dashboard/servers/${server.id}`,
1375	          },
1376	        });
1377	      }
1378	    }
1379	  }
1380	}
