11	
12	/**
13	 * Months left on a term, clamped to something sane.
14	 *
15	 * The clamp matters on the CREDIT side: `renewNow` can stack `expiresAt` many
16	 * terms into the future, and an unclamped credit multiplies the monthly delta by
17	 * every stacked month. The client estimate already clamped to one term while the
18	 * server did not, so the two disagreed and the server was the generous one.
19	 */
20	export function remainingMonths(expiresAt: Date | null, now: number, capMonths?: number): number {
21	  if (!expiresAt) return 0;
22	  const raw = Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
23	  return capMonths && capMonths > 0 ? Math.min(raw, capMonths) : raw;
24	}
25	
26	/**
27	 * The prorated difference between two monthly plan prices over the remaining
28	 * term, priced the way a FRESH order for the same product would be priced today.
29	 *
30	 * Why this exists (2026-07-25): proration used the raw list monthly delta while
31	 * the original purchase applied BOTH the term discount (lib/order.ts) and the
32	 * seasonal promo. Upgrading therefore cost far more than buying the target plan
33	 * outright for the same end date — on a 36-month term with a 30% promo running,
34	 * $1,044.45 to upgrade versus $665.08 fresh: the customer overpaid $379.37. The
35	 * mirror image was worse in kind though not yet reachable: the downgrade CREDIT
36	 * used the same undiscounted delta, so it refunded more than was ever paid — a
37	 * self-service money printer the moment the plan catalogue allows a downgrade.
38	 *
39	 * Both directions now price off the SAME function, so they cannot drift apart:
40	 *   effective monthly (term discount applied) → promo applied → × months left.
41	 *
42	 * `promo` is injected so a caller can price against a specific promo; it defaults
43	 * to whatever is running now, which is what a fresh order today would pay.
44	 */
45	export function prorateDeltaCents(opts: {
46	  fromMonthlyCents: number;
47	  toMonthlyCents: number;
48	  termMonths: number;
49	  monthsRemaining: number;
50	  promo?: Promo;
51	  now?: Date;
52	}): number {
53	  const promo = opts.promo ?? currentPromo(opts.now ?? new Date());
54	  const eff = (monthly: number) =>
55	    promoPriceCents(vpsEffectiveMonthly(monthly, opts.termMonths), promo);
56	  const delta = eff(opts.toMonthlyCents) - eff(opts.fromMonthlyCents);
57	  return Math.round(delta * Math.max(0, opts.monthsRemaining));
58	}
59	
60	/** Upgrade charge — never negative. */
61	export function prorateUpgradeCents(opts: Parameters<typeof prorateDeltaCents>[0]): number {
62	  return Math.max(0, prorateDeltaCents(opts));
63	}
64	
65	/** Downgrade credit — never negative; caller passes from=old, to=new. */
66	export function prorateDowngradeCreditCents(
67	  opts: Parameters<typeof prorateDeltaCents>[0]
68	): number {
69	  return Math.max(0, -prorateDeltaCents(opts));
70	}
