598	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
599	  // Spend path: block wallet debits while an admin is impersonating.
600	  await assertNotImpersonating();
601	  const { user, server } = await ownedServer(serverId);
602	  if (server.isFree || !server.expiresAt) return;
603	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
604	  if (!plan) return;
605	  const term = vpsTerm(server.termMonths);
606	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
607	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
608	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
609	    where: { serverId }, select: { id: true },
610	  }));
611	  // Extra root disk renews at the current per-GB price on top of the plan, exactly
612	  // like worker/billing.ts — the two renewal paths must never disagree.
613	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
614	  const extraDiskCents = extraDiskMonthly * term.months;
615	  const renewCents =
616	    vpsTermPriceCents(plan.priceCents, term.months) +
617	    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0) +
618	    extraDiskCents;
619	  const owner = await db.user.findUnique({ where: { id: server.userId } });
620	  if (!owner || owner.balanceCents < renewCents) {
621	    return { error: "Insufficient balance — top up your wallet first." };
622	  }
623	
624	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
625	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
626	  // can't both read E, both debit, and both write E+term (double-charge, one
627	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
628	  const E = server.expiresAt;
629	  const base = new Date(Math.max(E.getTime(), Date.now()));
630	  const newExpiry = addMonths(base, term.months);
631	  try {
632	    await db.$transaction(async (tx) => {
633	      // Compare-and-swap the expiry first; if it no longer equals E another
634	      // renewal already advanced it — bail without charging (tx rolls back).
635	      const adv = await tx.server.updateMany({
636	        where: { id: serverId, expiresAt: E },
637	        data: { expiresAt: newExpiry, suspendedNote: null, suspendReason: null },
638	      });
639	      if (adv.count === 0) throw new AlreadyRenewedError();
640	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
641	      await debitWallet(tx, server.userId, renewCents);
642	      await tx.walletTransaction.create({
643	        data: {
644	          userId: server.userId,
645	          amountCents: -renewCents,
646	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
647	        },
648	      });
649	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
650	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
651	      await tx.invoice.create({
652	        data: invoiceCreateData({
653	          userId: server.userId,
654	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
655	          status: "PAID",
656	          period: { start: E, end: newExpiry },
657	          lineItems: [
658	            {
659	              description: `${plan.name} VPS (${server.hostname}) — ${term.label}`,
660	              qty: 1,
661	              unitCents: renewCents - extraDiskCents,
662	              amountCents: renewCents - extraDiskCents,
663	            },
664	            ...(extraDiskCents > 0
665	              ? [
666	                  {
667	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
668	                    qty: 1,
669	                    unitCents: extraDiskCents,
670	                    amountCents: extraDiskCents,
671	                  },
672	                ]
673	              : []),
674	          ],
675	        }),
676	      });
677	    });
678	  } catch (e) {
679	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
680	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
681	    throw e;
682	  }
683	  await audit(user.id, "server.renew_now", serverId);
684	
685	  // An UNPAID-suspended server springs back to life once paid — but only that
686	  // kind. This used to fire for ANY suspended server, so a customer suspended for
687	  // outbound abuse could click "Renew now", pay, and put themselves straight back
688	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
689	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
690	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
691	    const pending = await db.job.count({
692	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
693	    });
694	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
695	  }
696	  revalidatePath(`/dashboard/servers/${serverId}`);
697	}
