309	/**
310	 * Backstop for the closed-tab case.
311	 *
312	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
313	 * runs. A customer who completes the Stripe page and then closes the tab has a
314	 * perfectly good card on file at Stripe and none on file here — and would be
315	 * dunned and suspended for it. This is the same class of bug as the Stripe
316	 * fulfilment incident: a browser redirect must never be the only trigger.
317	 *
318	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
319	 * newer than any `card.removed` row and no older than a week, so a card the
320	 * customer explicitly REMOVED can never be silently resurrected and charged.
321	 */
322	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
323	  if (!stripeConfigured()) return 0;
324	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
325	  const starts = await db.auditLog.findMany({
326	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
327	    orderBy: { createdAt: "desc" },
328	    take: 200,
329	  });
330	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
331	  if (userIds.length === 0) return 0;
332	
333	  let adopted = 0;
334	  for (const userId of userIds) {
335	    const user = await db.user.findUnique({ where: { id: userId } });
336	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
337	
338	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
339	    const removed = await db.auditLog.findFirst({
340	      where: { userId, action: CARD_REMOVED },
341	      orderBy: { createdAt: "desc" },
342	    });
343	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
344	
345	    try {
346	      const list = await stripe().paymentMethods.list({
347	        customer: user.stripeCustomerId,
348	        type: "card",
349	        limit: 5,
350	      });
351	      const pm = list.data[0]; // newest first
352	      if (!pm) continue;
353	      await persistCard(userId, user.stripeCustomerId, pm);
354	      await db.auditLog.create({
355	        data: {
356	          userId,
357	          action: "card.adopted",
358	          detail: `${cardDisplayLabel({
359	            brand: pm.card?.brand ?? null,
360	            last4: pm.card?.last4 ?? null,
361	            expMonth: pm.card?.exp_month ?? null,
362	            expYear: pm.card?.exp_year ?? null,
363	          })} (saved at Stripe but never confirmed in the browser)`,
364	        },
365	      });
366	      adopted++;
367	    } catch (e) {
368	      console.error(`[cards] could not adopt card for ${userId}`, e);
369	    }
370	  }
371	  return adopted;
372	}
