import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { stripe, stripeConfigured } from "@/lib/stripe";
import { getSettingInt } from "@/lib/settings";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (Math.round(dollars * 100) < minTopup) {
    return NextResponse.json(
      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
      { status: 400 },
    );
  }
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Nxeon wallet credit" },
          unit_amount: Math.round(dollars * 100),
        },
        quantity: 1,
      },
    ],
    metadata: { nxeonUserId: user.id },
    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}/dashboard/billing?canceled=1`,
  });
  return NextResponse.json({ url: session.url });
}
import { NextRequest, NextResponse } from "next/server";
import { stripeConfigured } from "@/lib/stripe";
import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";

/**
 * Checkout success-redirect target.
 *
 * This route no longer OWNS fulfilment — it asks the shared, idempotent
 * `fulfilCheckoutSession` to do it and follows whatever redirect comes back. The
 * webhook calls the identical function, so whichever arrives first fulfils and the
 * other is a harmless no-op.
 *
 * Until 2026-07-25 the logic lived here and was gated on whether the wallet credit
 * was inserted by THIS request — which made a browser redirect the fulfilment
 * trigger. If the webhook won the race, or the customer simply closed the tab
 * before this URL resolved, the payment was captured and nothing was provisioned:
 * no server, no error, no notification. Stripe's own guidance is explicit that a
 * redirect must never be what triggers fulfilment.
 */
export async function GET(req: NextRequest) {
  const base = process.env.APP_URL ?? "";
  const sessionId = req.nextUrl.searchParams.get("session_id");
  if (!stripeConfigured() || !sessionId) {
    return NextResponse.redirect(`${base}/dashboard/billing`);
  }
  try {
    const result = await fulfilCheckoutSession(sessionId, base);
    return NextResponse.redirect(result.redirect);
  } catch {
    // Never strand the customer on an error page: the webhook is an independent
    // backstop and will fulfil this session regardless of what happened here.
    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
  }
}
import { NextRequest, NextResponse } from "next/server";
import { stripe, stripeConfigured } from "@/lib/stripe";
import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";

export async function POST(req: NextRequest) {
  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
    return NextResponse.json({ error: "not configured" }, { status: 400 });
  }
  const sig = req.headers.get("stripe-signature");
  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
  const raw = await req.text();

  let event;
  try {
    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch {
    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as { id: string };
    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
    // throw the result away, which meant the webhook credited the wallet and then
    // — by winning the race — caused the success-redirect to see `credited: false`
    // and skip provisioning entirely. The webhook is the reliable signal (the
    // redirect may never happen at all), so it must be able to fulfil on its own.
    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
    // two callers racing is safe: exactly one does the work.
    //
    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
    // event, and the failure is already recorded on the FulfilledSession row and
    // surfaced to the customer.
    try {
      await fulfilCheckoutSession(session.id);
    } catch (e) {
      console.error("[stripe-webhook] fulfil failed", session.id, e);
    }
  }

  return NextResponse.json({ received: true });
}

