167	            amountCents: -priceCents,
168	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
169	          },
170	        });
171	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep matches zero
172	        // rows, throws AlreadyHandledError, and rolls this invoice back too.
173	        await tx.invoice.create({
174	          data: invoiceCreateData({
175	            userId: sub.userId,
176	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
177	            status: "PAID",
178	            period: { start: sub.expiresAt, end: newExpiry },
179	            lineItems: [
180	              { description: `${planName} — ${sub.domainName}`, qty: 1, unitCents: priceCents, amountCents: priceCents },
181	            ],
182	          }),
183	        });
184	      }
185	      await tx.auditLog.create({
186	        data: {
187	          userId: sub.userId,
188	          action: "billing.renewed",
189	          detail: `email ${sub.id} ${sub.domainName} ${money(priceCents)} -> ${ymd(newExpiry)}`,
190	        },
191	      });
192	    });
193	    return true;
194	  } catch (e) {
195	    if (e instanceof AlreadyHandledError) {
196	      console.log(`${LOG} email ${sub.id} already renewed by another pass — skipping`);
197	      return false;
198	    }
199	    if (e instanceof InsufficientBalanceError) {
200	      // Balance was spent between the read and the debit; the warn/grace path
201	      // picks it up on the next sweep.
202	      console.log(`${LOG} email ${sub.id} lost the race for funds — retrying next sweep`);
203	      return false;
204	    }
205	    throw e;
206	  }
207	}
