223	      action: "billing.suspended_unpaid",
224	      detail: `email ${sub.id} ${sub.domainName}`,
225	    },
226	  });
227	  await notify(
228	    sub.userId,
229	    `${sub.domainName} email suspended — payment overdue`,
230	    `Mail delivery is paused. Your mailboxes and their contents are kept — top up ${money(priceCents)} and renew from your email page to restore delivery.`,
231	    EMAIL_HREF
