324	/**
325	 * Charge + extend one volume atomically. Same compare-and-swap on `expiresAt`
326	 * as the email path, so re-running the sweep can never bill a second month.
327	 */
328	async function chargeVolumeRenewal(
329	  volume: { id: string; userId: string; name: string; sizeGB: number; expiresAt: Date | null; status: string },
330	  priceCents: number,
331	  newExpiry: Date
332	): Promise<boolean> {
333	  try {
334	    await db.$transaction(async (tx) => {
335	      const advanced = await tx.volume.updateMany({
336	        where: { id: volume.id, status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: volume.expiresAt },
337	        data: { expiresAt: newExpiry },
338	      });
339	      if (advanced.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
340	
341	      if (priceCents > 0) {
342	        await debitWallet(tx, volume.userId, priceCents);
343	        await tx.walletTransaction.create({
344	          data: {
345	            userId: volume.userId,
346	            amountCents: -priceCents,
347	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
348	          },
349	        });
350	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep rolls back.
351	        await tx.invoice.create({
352	          data: invoiceCreateData({
353	            userId: volume.userId,
354	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
355	            status: "PAID",
356	            period: { start: volume.expiresAt, end: newExpiry },
357	            lineItems: [
358	              { description: `Block storage — ${volume.name} (${volume.sizeGB} GB)`, qty: 1, unitCents: priceCents, amountCents: priceCents },
359	            ],
360	          }),
361	        });
362	      }
363	      await tx.auditLog.create({
364	        data: {
365	          userId: volume.userId,
366	          action: "billing.renewed",
367	          detail: `volume ${volume.id} ${volume.name} ${money(priceCents)} -> ${ymd(newExpiry)}`,
368	        },
369	      });
370	    });
371	    return true;
372	  } catch (e) {
373	    if (e instanceof AlreadyHandledError) {
374	      console.log(`${LOG} volume ${volume.id} already renewed by another pass — skipping`);
375	      return false;
376	    }
377	    if (e instanceof InsufficientBalanceError) {
378	      console.log(`${LOG} volume ${volume.id} lost the race for funds — retrying next sweep`);
379	      return false;
380	    }
381	    throw e;
382	  }
383	}
